param([string]$ComPort = "COM3")
$ErrorActionPreference = "Stop"
$p = New-Object System.IO.Ports.SerialPort $ComPort, 115200
$p.DtrEnable = $true
$p.Open()
try {
  $boot = ""
  $deadline = (Get-Date).AddSeconds(25)
  while ((Get-Date) -lt $deadline) {
    if ($p.BytesToRead -gt 0) { $boot += $p.ReadExisting() }
    if ($boot -match "nsh>") { break }
    Start-Sleep -Milliseconds 100
  }
  Write-Host "===== BOOT ====="
  Write-Host $boot
  $p.DiscardInBuffer()
  $p.Write("`r")
  Start-Sleep -Milliseconds 400
  $p.Write("?`r")
  Start-Sleep -Seconds 3
  $h = ""
  while ($p.BytesToRead -gt 0) { $h += $p.ReadExisting(); Start-Sleep -Milliseconds 40 }
  Write-Host "===== HELP ====="
  Write-Host $h
  Write-Host ("HAS_AI=" + ($h -match "ai_agent"))
  Write-Host ("HAS_VGHMI=" + ($h -match "vghmi"))
  Write-Host ("HAS_VGMODBUS=" + ($h -match "vgmodbus"))
}
finally {
  if ($p.IsOpen) { $p.Close() }
}

