input.contents:
/****************************************************************************
 * VelaGuard eMMC provision store (encrypted LLM credentials).
 ****************************************************************************/

#include "vg_provision.h"

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#ifdef __NuttX__
#  include <nuttx/config.h>
#endif

#define VG_PROVISION_DIR "/data/velaguard/provision"

static int json_escape(const char *in, char *out, size_t outsz)
{
  size_t o = 0;

  if (outsz == 0)
    {
      return -EINVAL;
    }

  for (; *in != '\0'; in++)
    {
      char c = *in;

      if (c == '"' || c == '\\')
        {
          if (o + 2 >= outsz)
            {
              return -ENOSPC;
            }

          out[o++] = '\\';
        }

      if (o + 1 >= outsz)
        {
          return -ENOSPC;
        }

      out[o++] = c;
    }

  out[o] = '\0';
  return 0;
}

static int json_get_string(const char *json, const char *key,
                           char *out, size_t outsz)
{
  char pattern[48];
  const char *p;
  const char *start;
  size_t i;

  snprintf(pattern, sizeof(pattern), "\"%s\"", key);
  p = strstr(json, pattern);
  if (p == NULL)
    {
      return -ENOENT;
    }

  p = strchr(p, ':');
  if (p == NULL)
    {
      return -EINVAL;
    }

  p++;
  while (*p == ' ' || *p == '\t')
    {
      p++;
    }

  if (*p != '"')
    {
      return -EINVAL;
    }

  start = p + 1;
  for (i = 0; start[i] != '\0'; i++)
    {
      if (start[i] == '"' && (i == 0 || start[i - 1] != '\\'))
        {
          if (i + 1 >= outsz)
            {
              return -ENOSPC;
            }

          memcpy(out, start, i);
          out[i] = '\0';
          return 0;
        }
    }

  return -EINVAL;
}

int vg_provision_read_uid(uint8_t uid[VG_PROVISION_UID_LEN])
{
#ifdef __NuttX__
  const volatile uint32_t *base =
    (const volatile uint32_t *)0x1ff1e800;

  memcpy(uid, base, VG_PROVISION_UID_LEN);
  return 0;
#else
  memset(uid, 0xab, VG_PROVISION_UID_LEN);
  return 0;
#endif
}

int vg_provision_parse_endpoint(const char *endpoint,
                                char *host, size_t hostsz,
                                char *path, size_t pathsz,
                                char *port, size_t portsz)
{
  const char *p;
  const char *slash;
  const char *host_start;
  size_t host_len;

  if (endpoint == NULL || host == NULL || path == NULL || port == NULL)
    {
      return -EINVAL;
    }

  snprintf(port, portsz, "443");

  p = endpoint;
  if (strncmp(p, "https://", 8) == 0)
    {
      p += 8;
    }
  else if (strncmp(p, "http://", 7) == 0)
    {
      p += 7;
      snprintf(port, portsz, "80");
    }

  host_start = p;
  slash = strchr(p, '/');
  if (slash == NULL)
    {
      host_len = strlen(host_start);
      if (host_len + 1 > hostsz)
        {
          return -ENOSPC;
        }

      memcpy(host, host_start, host_len);
      host[host_len] = '\0';
      snprintf(path, pathsz, "/v1/chat/completions");
      return 0;
    }

  host_len = (size_t)(slash - host_start);
  if (host_len + 1 > hostsz)
    {
      return -ENOSPC;
    }

  memcpy(host, host_start, host_len);
  host[host_len] = '\0';

  if (strcmp(slash, "/v1") == 0 || strcmp(slash, "/v1/") == 0)
    {
      snprintf(path, pathsz, "/v1/chat/completions");
    }
  else
    {
      snprintf(path, pathsz, "%s", slash);
      if (strstr(path, "chat/completions") == NULL)
        {
          size_t n = strlen(path);

          if (n + 1 < pathsz && path[n - 1] != '/')
            {
              strcat(path, "/");
              n++;
            }

          if (n + 20 < pathsz)
            {
              strcat(path, "chat/completions");
            }
        }
    }

  return 0;
}

static int cred_to_json(const struct vg_llm_credentials *cred,
                        char *out, size_t outsz)
{
  char key_esc[VG_PROVISION_API_KEY_MAX * 2];
  char host_esc[VG_PROVISION_HOST_MAX * 2];
  char path_esc[VG_PROVISION_PATH_MAX * 2];
  int ret;

  ret = json_escape(cred->api_key, key_esc, sizeof(key_esc));
  if (ret < 0)
    {
      return ret;
    }

  ret = json_escape(cred->host, host_esc, sizeof(host_esc));
  if (ret < 0)
    {
      return ret;
    }

  ret = json_escape(cred->path, path_esc, sizeof(path_esc));
  if (ret < 0)
    {
      return ret;
    }

  snprintf(out, outsz,
           "{"
           "\"host\":\"%s\","
           "\"path\":\"%s\","
           "\"port\":\"%s\","
           "\"model\":\"%s\","
           "\"api_key\":\"%s\""
           "}",
           host_esc, path_esc, cred->port, cred->model, key_esc);
  return 0;
}

static int json_to_cred(const char *json, struct vg_llm_credentials *out)
{
  int ret;

  memset(out, 0, sizeof(*out));
  ret = json_get_string(json, "host", out->host, sizeof(out->host));
  if (ret < 0)
    {
      return ret;
    }

  ret = json_get_string(json, "path", out->path, sizeof(out->path));
  if (ret < 0)
    {
      return ret;
    }

  ret = json_get_string(json, "port", out->port, sizeof(out->port));
  if (ret < 0)
    {
      return ret;
    }

  ret = json_get_string(json, "model", out->model, sizeof(out->model));
  if (ret < 0)
    {
      return ret;
    }

  return json_get_string(json, "api_key", out->api_key, sizeof(out->api_key));
}

bool vg_provision_is_present(void)
{
  struct stat st;

  return stat(VG_PROVISION_FILE, &st) == 0 && st.st_size > 0;
}

int vg_provision_seal(const struct vg_llm_credentials *cred)
{
  uint8_t uid[VG_PROVISION_UID_LEN];
  char plain[640];
  uint8_t blob[768];
  size_t blob_len;
  int fd;
  int ret;

  if (cred == NULL || cred->api_key[0] == '\0' || cred->host[0] == '\0')
    {
      return -EINVAL;
    }

  ret = mkdir(VG_PROVISION_DIR, 0700);
  if (ret < 0 && errno != EEXIST)
    {
      return -errno;
    }

  ret = cred_to_json(cred, plain, sizeof(plain));
  if (ret < 0)
    {
      return ret;
    }

  ret = vg_provision_read_uid(uid);
  if (ret < 0)
    {
      return ret;
    }

  ret = vg_provision_crypto_seal(uid, (const uint8_t *)plain, strlen(plain),
                                 blob, sizeof(blob), &blob_len);
  if (ret < 0)
    {
      return ret;
    }

  fd = open(VG_PROVISION_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0600);
  if (fd < 0)
    {
      return -errno;
    }

  if (write(fd, blob, blob_len) != (ssize_t)blob_len)
    {
      close(fd);
      return -EIO;
    }

  close(fd);
  return 0;
}

int vg_provision_load(struct vg_llm_credentials *out)
{
  uint8_t uid[VG_PROVISION_UID_LEN];
  uint8_t blob[768];
  char plain[640];
  size_t plain_len;
  ssize_t n;
  int fd;
  int ret;

  if (out == NULL)
    {
      return -EINVAL;
    }

  fd = open(VG_PROVISION_FILE, O_RDONLY);
  if (fd < 0)
    {
      return -errno;
    }

  n = read(fd, blob, sizeof(blob));
  close(fd);
  if (n <= 0)
    {
      return (n == 0) ? -EINVAL : -EIO;
    }

  ret = vg_provision_read_uid(uid);
  if (ret < 0)
    {
      return ret;
    }

  ret = vg_provision_crypto_open(uid, blob, (size_t)n,
                                 (uint8_t *)plain, sizeof(plain), &plain_len);
  if (ret < 0)
    {
      return ret;
    }

  plain[plain_len] = '\0';
  return json_to_cred(plain, out);
}

int vg_provision_apply_llm_config(void)
{
  struct vg_llm_credentials cred;
  char key_esc[VG_PROVISION_API_KEY_MAX * 2];
  char backend[512];
  char body[1024];
  int fd;
  int ret;

  if (!vg_provision_is_present())
    {
      return -ENOENT;
    }

  ret = vg_provision_load(&cred);
  if (ret < 0)
    {
      return ret;
    }

  ret = mkdir("/data/agent/config", 0700);
  if (ret < 0 && errno != EEXIST)
    {
      return -errno;
    }

  ret = json_escape(cred.api_key, key_esc, sizeof(key_esc));
  if (ret < 0)
    {
      return ret;
    }

  snprintf(backend, sizeof(backend),
           "{\\\"host\\\":\\\"%s\\\",\\\"path\\\":\\\"%s\\\","
           "\\\"port\\\":\\\"%s\\\",\\\"api_key\\\":\\\"%s\\\","
           "\\\"model\\\":\\\"%s\\\",\\\"priority\\\":0,\\\"cost_tier\\\":1}",
           cred.host, cred.path, cred.port, key_esc, cred.model);

  snprintf(body, sizeof(body),
           "{"
           "\"llm_host\":\"%s\","
           "\"llm_path\":\"%s\","
           "\"llm_port\":\"%s\","
           "\"model\":\"%s\","
           "\"api_key\":\"%s\","
           "\"llm_backend_0\":\"%s\""
           "}",
           cred.host, cred.path, cred.port, cred.model, key_esc, backend);

  fd = open("/data/agent/config/config.json",
            O_WRONLY | O_CREAT | O_TRUNC, 0600);
  if (fd < 0)
    {
      return -errno;
    }

  if (write(fd, body, strlen(body)) != (ssize_t)strlen(body))
    {
      close(fd);
      return -EIO;
    }

  close(fd);
  return 0;
}

/****************************************************************************
 * NSH: vgprovision — seal / inspect encrypted LLM credentials on eMMC.
 ****************************************************************************/

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <nuttx/config.h>

#include "vg_provision.h"

static void usage(void)
{
  printf("Usage:\n");
  printf("  vgprovision uid\n");
  printf("  vgprovision status\n");
  printf("  vgprovision seal <endpoint_url> <api_key>\n");
}

static void print_uid(void)
{
  uint8_t uid[VG_PROVISION_UID_LEN];
  int ret;

  ret = vg_provision_read_uid(uid);
  if (ret < 0)
    {
      printf("vgprovision: uid error %d\n", ret);
      return;
    }

  printf("vgprovision: uid=");
  for (int i = 0; i < VG_PROVISION_UID_LEN; i++)
    {
      printf("%02x", uid[i]);
    }

  printf("\n");
}

int main(int argc, char *argv[])
{
  if (argc < 2)
    {
      usage();
      return 1;
    }

  if (strcmp(argv[1], "uid") == 0)
    {
      print_uid();
      return 0;
    }

  if (strcmp(argv[1], "status") == 0)
    {
      struct vg_llm_credentials cred;
      int ret;

      if (!vg_provision_is_present())
        {
          printf("vgprovision: not provisioned\n");
          return 1;
        }

      ret = vg_provision_load(&cred);
      if (ret < 0)
        {
          printf("vgprovision: load failed %d\n", ret);
          return 1;
        }

      printf("vgprovision: OK host=%s model=%s key_len=%zu\n",
             cred.host, cred.model, strlen(cred.api_key));
      return 0;
    }

  if (strcmp(argv[1], "seal") == 0)
    {
      struct vg_llm_credentials cred;
      int ret;

      if (argc < 4)
        {
          usage();
          return 1;
        }

      memset(&cred, 0, sizeof(cred));
      snprintf(cred.model, sizeof(cred.model), "mimo-v2.5");
      ret = vg_provision_parse_endpoint(argv[2],
                                      cred.host, sizeof(cred.host),
                                      cred.path, sizeof(cred.path),
                                      cred.port, sizeof(cred.port));
      if (ret < 0)
        {
          printf("vgprovision: endpoint parse %d\n", ret);
          return 1;
        }

      snprintf(cred.api_key, sizeof(cred.api_key), "%s", argv[3]);
      ret = vg_provision_seal(&cred);
      if (ret < 0)
        {
          printf("vgprovision: seal failed %d\n", ret);
          return 1;
        }

      ret = vg_provision_apply_llm_config();
      printf("vgprovision: sealed %s (apply %d)\n", VG_PROVISION_FILE, ret);
