static bool config_has_api_key(void)
{
  int fd;
  char buf[640];
  ssize_t n;
  const char *p;
  const char *val;

  fd = open("/data/agent/config/config.json", O_RDONLY);
  if (fd < 0)
    {
      return false;
    }

  n = read(fd, buf, sizeof(buf) - 1);
  close(fd);
  if (n <= 0)
    {
      return false;
    }

  buf[n] = '\0';
  p = strstr(buf, "\"api_key\"");
  if (p == NULL)
    {
      return false;
    }

  p = strchr(p, ':');
  if (p == NULL)
    {
      return false;
    }

  p++;
  while (*p == ' ' || *p == '\t')
    {
      p++;
    }

  if (*p != '"')
    {
      return false;
    }

  val = p + 1;
  return (val[0] != '\0' && val[0] != '"');
}

static int json_escape(const char *in, char *out, size_t outsz)
{
  size_t o = 0;

  if (outsz == 0)
    {
      return -EINVAL;
    }

  for (; *in != '\0'; in++)
    {
      char c = *in;
      if (c == '"' || c == '\\')
        {
          if (o + 2 >= outsz)
            {
              return -ENOSPC;
            }

          out[o++] = '\\';
        }

      if (o + 1 >= outsz)
        {
          return -ENOSPC;
        }

      out[o++] = c;
    }

  out[o] = '\0';
  return 0;
}

static void seed_llm_config_if_needed(void)
{
  char key_esc[192];
  char backend[512];
  char body[1024];
  int fd;
  int ret;

  if (VG_AGENT_LLM_API_KEY[0] == '\0')
    {
      return;
    }

  if (config_has_api_key())
    {
      return;
    }

  ret = mkdir("/data/agent/config", 0700);
  if (ret < 0 && errno != EEXIST)
    {
      return;
    }

  ret = json_escape(VG_AGENT_LLM_API_KEY, key_esc, sizeof(key_esc));
  if (ret < 0)
    {
      return;
    }

  snprintf(backend, sizeof(backend),
           "{\\\"host\\\":\\\"%s\\\",\\\"path\\\":\\\"%s\\\","
           "\\\"port\\\":\\\"%s\\\",\\\"api_key\\\":\\\"%s\\\","
           "\\\"model\\\":\\\"%s\\\",\\\"priority\\\":0,\\\"cost_tier\\\":1}",
           VG_AGENT_LLM_HOST, VG_AGENT_LLM_PATH, VG_AGENT_LLM_PORT,
           key_esc, VG_AGENT_LLM_MODEL);

  snprintf(body, sizeof(body),
           "{"
           "\"llm_host\":\"%s\","
           "\"llm_path\":\"%s\","
           "\"llm_port\":\"%s\","
           "\"model\":\"%s\","
           "\"api_key\":\"%s\","
           "\"llm_backend_0\":\"%s\""
           "}",
           VG_AGENT_LLM_HOST, VG_AGENT_LLM_PATH, VG_AGENT_LLM_PORT,
           VG_AGENT_LLM_MODEL, key_esc, backend);

  fd = open("/data/agent/config/config.json",
            O_WRONLY | O_CREAT | O_TRUNC, 0600);
  if (fd < 0)
    {
      return;
    }

  if (write(fd, body, strlen(body)) != (ssize_t)strlen(body))
    {
      close(fd);
      return;
    }

  close(fd);
}

