# Encrypt MiMo secrets from secrets/ and write to board eMMC via COM3.
# Usage: powershell.exe -ExecutionPolicy Bypass -File scripts/provision-llm-from-secrets.ps1

param(
  [string]$ComPort = "COM3",
  [string]$ContestRoot = ""
)

$ErrorActionPreference = "Stop"
if ($ContestRoot -eq "") { $ContestRoot = Split-Path -Parent $PSScriptRoot }

$keyFile = Join-Path $ContestRoot "secrets\agent_llm.key"
$epFile  = Join-Path $ContestRoot "secrets\agent_llm.endpoint"
$packPy  = Join-Path $ContestRoot "scripts\vg-provision-pack.py"
$plain   = Join-Path $ContestRoot ".debug\provision-plain.json"
$blob    = Join-Path $ContestRoot ".debug\llm_secrets.v1"

if (-not (Test-Path $keyFile) -or -not (Test-Path $epFile)) {
  throw "Missing secrets/agent_llm.key or secrets/agent_llm.endpoint"
}

$key = (Get-Content -LiteralPath $keyFile -Raw).Trim()
$endpoint = (Get-Content -LiteralPath $epFile -Raw).Trim()

$host = $endpoint
$path = "/v1/chat/completions"
$port = "443"
if ($endpoint -match '^https?://') {
  if ($endpoint.StartsWith("https://")) { $rest = $endpoint.Substring(8) } else { $rest = $endpoint.Substring(7); $port = "80" }
  if ($rest -match '/') {
    $hp = $rest.Split('/', 2)
    $host = $hp[0]
    $path = '/' + $hp[1]
    if ($path -eq '/v1' -or $path -eq '/v1/') { $path = '/v1/chat/completions' }
    elseif ($path -notmatch 'chat/completions') { $path = $path.TrimEnd('/') + '/chat/completions' }
  } else { $host = $rest }
}

$obj = @{ host = $host; path = $path; port = $port; model = 'mimo-v2.5'; api_key = $key }
$obj | ConvertTo-Json -Compress | Set-Content -LiteralPath $plain -Encoding UTF8 -NoNewline

function Send-Cmd {
  param([System.IO.Ports.SerialPort]$Port, [string]$Cmd, [int]$WaitMs = 1200)
  $Port.DiscardInBuffer()
  $Port.WriteLine($Cmd)
  Start-Sleep -Milliseconds $WaitMs
  return $Port.ReadExisting()
}

$port = New-Object System.IO.Ports.SerialPort $ComPort, 115200
$port.ReadTimeout = 15000
$port.NewLine = "`n"
$port.Open()
Start-Sleep -Milliseconds 800
while ($port.BytesToRead -gt 0) { [void]$port.ReadExisting(); Start-Sleep -Milliseconds 80 }

Write-Host "[provision] wait nsh>"
$deadline = (Get-Date).AddSeconds(25)
$boot = ""
while ((Get-Date) -lt $deadline) {
  if ($port.BytesToRead -gt 0) { $boot += $port.ReadExisting() }
  if ($boot -match 'nsh>') { break }
  Start-Sleep -Milliseconds 200
}
if ($boot -notmatch 'nsh>') { $port.Close(); throw "no nsh> prompt" }

$uidOut = Send-Cmd $port "vgprovision uid" 2500
if ($uidOut -notmatch 'uid=([0-9a-fA-F]{24})') { $port.Close(); throw "vgprovision uid failed: $uidOut" }
$uid = $Matches[1]
Write-Host "[provision] uid=$uid"

python3 $packPy $uid $plain | Set-Content -LiteralPath $blob -Encoding Byte -NoNewline
$hex = -join ((Get-Content -LiteralPath $blob -Encoding Byte) | ForEach-Object { '{0:x2}' -f $_ })
Write-Host "[provision] blob bytes=$((Get-Item $blob).Length)"

Send-Cmd $port "vgprovision wipe" 1500 | Out-Null
for ($i = 0; $i -lt $hex.Length; $i += 32) {
  $chunk = $hex.Substring($i, [Math]::Min(32, $hex.Length - $i))
  Send-Cmd $port "vgprovision put $chunk" 200 | Out-Null
}
$out = Send-Cmd $port "vgprovision commit" 3000
Write-Host $out
$st = Send-Cmd $port "vgprovision status" 2500
Write-Host $st
$port.Close()

if ($st -notmatch 'vgprovision: OK') { throw "provision status failed" }
Write-Host "[provision] OK"

